import React, { useState } from 'react';
import { Button } from '@mui/material';
import { Core } from '@walletconnect/core';
import { WalletKit } from '@reown/walletkit';

// 初始化 WalletConnect Core
const core = new Core({
  projectId: '04c0b2d9008965dbbb384a7ea155b5f7', // 替換為你的 Project ID
});

// Metadata 信息（用於顯示在錢包連接彈窗中）
const metadata = {
  name: 'ESG Project',
  description: 'A wallet connection example',
  url: 'https://chelseywang.github.io/my-esg', // 部屬後的網址
  icons: ['https://assets.reown.com/reown-profile-pic.png'],
};

const ConnectWalletButton = () => {
  const [walletConnected, setWalletConnected] = useState(false);
  const [walletInfo, setWalletInfo] = useState(null); // 用於存儲錢包信息

  const handleConnect = async () => {
    try {
      // 初始化 WalletKit
      const walletKit = await WalletKit.init({ core, metadata });
      // 發起連接請求
      const wallet = await walletKit.connect();

      // 如果連接成功，保存錢包信息
      console.log('Connected wallet:', wallet);
      setWalletInfo(wallet);
      setWalletConnected(true);
    } catch (error) {
      console.error('Wallet connection failed:', error);
    }
  };

  return (
    <div>
      <Button
  variant="contained"
  sx={{
    color: 'white',
    backgroundColor: walletConnected ? 'green' : 'blue',
    '&:hover': {
      backgroundColor: walletConnected ? 'darkgreen' : 'darkblue',
    },
  }}
  onClick={handleConnect} // 確保此處有綁定事件處理函數
>
  {walletConnected ? 'Wallet Connected' : 'Connect Wallet'}
</Button>

      {walletInfo && (
        <div style={{ marginTop: '20px', color: 'white' }}>
          <p>Wallet Address: {walletInfo.accounts[0]}</p>
          <p>Chain ID: {walletInfo.chainId}</p>
        </div>
      )}
    </div>
  );
};

export default ConnectWalletButton;
